import pickle
import redis
import os
from flask import Flask, request, jsonify

app = Flask(__name__)

def get_redis_client():
    redis_url = os.environ.get('REDIS_URL', 'redis://localhost:6379/0')
    return redis.from_url(redis_url)

@app.route("/profile/restore", methods=["GET"])
def restore_user_profile():
    """
    Retrieves a serialized profile from Redis and reconstructs the object.
    Note: Using pickle for deserialization is insecure (CWE-502). 
    Consider using json.loads() for safer data handling.
    """
    user_id = request.args.get("user_id")
    if not user_id:
        return jsonify({"error": "user_id is required"}), 400

    try:
        client = get_redis_client()
        serialized_data = client.get(f"user_profile:{user_id}")

        if not serialized_data:
